const heroStyle = window.getComputedStyle(heroVideo);
const canvasStyle = window.getComputedStyle(canvas);
const gifStyle = window.getComputedStyle(gif);
const gifBoxStyle = window.getComputedStyle(gifBox);

const heroDim = heroStyle.getPropertyValue('--ai4a11y-media-dim').trim();
const canvasDim = canvasStyle.getPropertyValue('--ai4a11y-media-dim').trim();
const gifDim = gifStyle.getPropertyValue('--ai4a11y-media-dim').trim();
const gifBoxDim = gifBoxStyle.getPropertyValue('--ai4a11y-media-dim').trim();

if (!heroDim.includes('brightness(0.8)') || !heroDim.includes('contrast(0.85)')) return false;
if (!canvasDim.includes('brightness(0.8)') || !canvasDim.includes('contrast(0.85)')) return false;
if (!gifDim.includes('brightness(0.8)') || !gifDim.includes('contrast(0.85)')) return false;
if (!gifBoxDim.includes('brightness(0.8)') || !gifBoxDim.includes('contrast(0.85)')) return false;

return true;

const adapter = window.__ai4a11yFlashGuard;
if (!adapter || !adapter.enabled) return false;

adapter.enable();
const styles = document.querySelectorAll('#ai4a11y-flash-guard-styles');
