const lateVideo = document.createElement('video');
lateVideo.id = 'late-video';
lateVideo.setAttribute('autoplay', '');
lateVideo.setAttribute('muted', '');
lateVideo.setAttribute('aria-label', 'Late loaded stream');
document.body.appendChild(lateVideo);

